Hi Bob,

I finished coding the most complex integrated stock assessment model in STAN and got it to successfully compile in C++. However, I'm getting error messages with the Dirichlet functions as the sum of probabilities need to add to 1. This might be a fundamental difference with the JAGS/BUS Dirichlet function and the STAN code, or the code I'm using from JAGS isn't appropriate.   Anyway, below I post the JAGS code, STAN code, and a sample of the error message.

Here is the JAGS code for the Integrated model (modified from Mäntyniemi et al. 2013 Can. J. Fish. Aquat. Sci. 70: 1317–1326)

model{

#######################################################
# Population dynamics
# The population dynamics model tracks the total number
# in the population through time. The time step is one year (y)
#
# To improve the performance of MCMC, the total number of fish is relative to
# abundance in the 1st year

for(y in 1:Y){                        # Loop over years
N[y+1]<-N[y]*rho[y,1]+R[y+1]          # N[y] number of fish relative to N0
R[y+1]<-exp(LR[y])                    # R[y] number of recruits relative to N0
LR[y]~dnorm(MR[y,stockr],TRe[shr])
MR[y,1]<-log(E[y]*K/(K/alpha+E[y]))-0.5/(1/log(CVR*CVR+1))                             # Beverton-holt
MR[y,2]<-log(E[y]*alpha*exp(-alpha*E[y]/(K*exp(1))))-0.5/(1/log(CVR*CVR+1))          # Ricker

E[y]<-N[y]*0.5*1000*sum(e[y,1:A])     # E[y] number of eggs spawned
# dependent mortality
ap[y+1,1]<-R[y+1]/N[y+1]                   # proportion of recruits in the population in the beg. of
# next year
C[y]<-N[y]*rho[y,2]*N0                     # Expected catch in numbers
BC[y]<-inprod(w[y,1:A],pc[y,1:A])*C[y]     # Expected biomass of the catch
B[y]<-inprod(w[y,1:A],p[y,1:A])*N0*N[y]     # Biomass of the population
Clupe[y]<-B[y]                   # Total biomass of sprat and herring

# the role of rho vector is to implement a tiny additional stochastic component to population dynamics
# this makes MCMC to run a whole lot faster!

rho[y,1:2]~ddirch(arho[y,1:2])
arho[y,1]<-(sum(d[y,1:A]))*10000
arho[y,2]<-(sum(g[y,1:A]))*10000

for(a in 1:A){ # loop through age classes within a year
d[y,a]<-exp(-Z[y,a])*p[y,a]           # surv to end of year
g[y,a]<-s[y,a]*(F[y,a]/Z[y,a])*(1-exp(-Z[y,a]))*p[y,a]   # harvest rate and gear sel.
ps[y,a]<-d[y,a]/(sum(d[y,1:A]))            # age distr. in the end of the year
pc[y,a]<-g[y,a]/(sum(g[y,1:A]))            # age distr. in the catch
e[y,a]<-((exp(-Z[y,a]*0.6)*p[y,a])/(sum(exp(-Z[y,a]*0.6)*p[y,a])))*w[y,a]*mat[y,a]*fec[y,a]    # eggs per spawner at age a
}

# evolution of the age distribution

for(a in 1:A-2){
ap[y+1,a+1]<-ps[y,a]*(1-ap[y+1,1])   # age dist in the beg of next year
}
ap[y+1,A]<-(ps[y,A-1]+ps[y,A])*(1-ap[y+1,1])    # plus group: all fish at age A and older than A

p[y+1,1:A]~ddirch(ape[y+1,1:A])  # small amount of Dirichlet variation to improve MCMC speed

for(a in 1:A){
Z[y,a]<-M[y,a]+F[y,a]            # Total mortality rate= Natural mortality + fishing mortality
ape[y+1,a]<-10000*ap[y+1,a]       # parameters for the dirichlet distribution
}
}
#### Priors for population dynamic parameters
# Initial state : minimally informative Dirichlet prior for the age composition
p[1,1:A]~ddirch(ape[1,1:A])
for(a in 1:A){
ape[1,a]<-1/A
}
# Recruitment of the first year
R[1]<-N[1]*p[1,1]

# Initial population size relative to K
N[1]<-1 #

N0~dlnorm(10,1/log(0.8*0.8+1))

# Asymptotic number of recruits, when eggs -> inf
K<-exp(LK)
LK~dnorm(0,1/log(2))

# Survival of eggs, when eggs -> 0
alpha<-exp(Lalpha)
Lalpha~dnorm(log(0.00001),1/log(0.5*0.5+1))

# Prior for the CV of annual recruitment residuals
CVR~dbeta(1,2)

# prior for the stock-recruitment model
stockr~dcat(pstockr[1:2])
pstockr[1]<-1/2
pstockr[2]<-1/2

# constants for dirichlet distributions. These need to be 'large', so that the dirichlet variation does not
# affect the parameter estimates. This is just a trick to speed up computation in JAGS

shr~dcat(psh[1:6])
for (i in 1:6){
TRe[i]<-1/log(CVR*CVR+1)
psh[i]<-1/6
}

#################################################################
# End of population dynamics
#################################################################

#################################################################
# Model for natural mortality M[y,a]
# M[y,a] is assumed to depend on weight as proposed by Gislasson
# et al.
#

  for(y in 1:Y){
    for(a in 1:A){
    log(M[y,a])<--G*log(w[y,a]*1000)    # w[y,a]: weight at age
    }
  }
G~dlnorm(log(0.25),1/log(0.1*0.1+1))T(0.1,0.5)                 # hyperpriors for  G

#################################################################
# Model for fishing mortality F[y,a]
# F[y,a] is assumed to depend on annual level of fishing pressure and
# on availability v[y,a] of fish of different ages at fishing grounds

  for(y in 1:Y){
    for(a in 1:A){
    F[y,a]<-exp(logF[y,a])
    logF[y,a]~dnorm((eF[y]+log(v[y,a])+medF),1/log(CVaF*CVaF+1))
    }
  eF[y]~dnorm(0,1/log(CVyF*CVyF+1))  # random effect of fishing pressure
  }

# median fishing pressure across years, on log-scale
medF~dnorm(log(0.2),1/log(0.5*0.5+1))
# prior for CV of fishing pressure across years
CVyF~dbeta(2,8)
# prior for CV of fishing mortality between age groups, within a year
CVaF~dbeta(2,8)

####################################################################
# Model for the relative availability of fish. This assumes that the
# availability of fish at length 23 = 1
#
  for(y in 1:Y){
    for(a in 1:A){
    probit(rv[y,a])<-(L[y,a]-fl50)/sdfl # probit model: S-shaped curve
    v[y,a]<-rv[y,a]/v23                 # relate to 23cm fish
    }
  }
probit(v23)<-(23-fl50)/sdfl             # availability of 20cm fish
fl50~dunif(0,40)                        # inflexion point
sdfl~dunif(0,40)                        # slope of the curve

####################################################################
# Model for the selectivity of the fishing gear: probability that
# a fish that goes into the fishing gear (trawl) becomes caught
#

  for(y in 1:Y){
    for(a in 1:A){
      for(i in 1:2){
      logit(sg[y,a,i])<-alphav[i]+betav[i]*L[y,a]  # Logistic curve for each gear
      }
    s[y,a]<-inprod(ge[1:2],sg[y,a,1:2])            # overall selectivity
    }
  }
betav[1]<-0.468                    # PIS data
alphav[1]<--12.34                   # PIS data
betav[2]<-0.470                    # Comm data
alphav[2]<--16.79           # Comm data

ge[1:2]~ddirch(age[1:2])
age[1]<-1/2
age[2]<-1/2

#####################################################################
# Model for fecundity : number of eggs spawned produced/gram of
# mature female herring

  for(y in 1:Y){
    for(a in 1:A){
    fec[y,a]<-af*pow(w[y,a],bf)
    }
  }
# Priors for parameters
af~dnorm(9.6849,0.5)
bf~dnorm(0.456,1000)T(0.2,1.4)

#####################################################################
# Model for growth of herring : Von Bertalanffy curve
# for mean length at age L[y,a]

  for(y in 1:Y){
   for(a in 1:A){
    LogL[y+1,a+1]~dnorm((log((Linf-L[y,a])+L[y,a])),(1/log(CVL*CVL+1)))                  # growth process error
L[y+1,a+1]<-exp(LogL[y+1,a+1])                          # transform to original scale
w[y,a]~dlnorm(((-11.57)+2.979*log(L[y,a])),100)                            # weight obs model
}

L[y,1]~dlnorm(0,1)  # prior for the mean length of age 1 herring
}
# prior for the mean length at age in the first year
  for(a in 2:A){
  L[1,a]~dlnorm(0,1)
  }

# priors for the parameters of the growth process. Fixed for now, uncertainty to be included
Linf~dnorm(25,0.11)
CVL~dbeta(1,9)

####################################################################
# Model for fishery observations

  for(y in 1:Y){
  logC[y]~dnorm(log(BC[y]),(1/log(0.05*0.05+1)))                # Normal prior for total catch in biomass
  }

#####################################################################
# Model for survey observations:
# Total catch per unit of effort in echo sounding surveys
# no age structure just yet

  for(y in 1:Y){
    for(a in 1:A){
    pz[y,a]<-sv[y,a]*p[y,a]*exp(-Z[y,a]*0.8)    # survival to survey, including survey selection
    apz[y,a]<-pz[y,a]/Tpz[y]                       # age distribution in survey
    }
  Tpz[y]<-sum(pz[y,1:A])                         # mean survival to survey
  BS[y]<-inprod(w[y,1:A],apz[y,1:A])*N[y]*Tpz[y]*N0 # Population biomass observable at survey time
  }

  # Selectivity of the survey: proportion of age class in the survey area, function of mean length

  for(y in 1:Y){
    for(a in 1:A){
    probit(svr[y,a])<-(L[y,a]-surv50)/sdsurv
    sv[y,a]<-svr[y,a]/phi((23-surv50)/sdsurv)
    }
  logS[y]~dnorm((log(BS[y]*bs)-0.5/(1/log(CVS*CVS+1))),1/log(CVS*CVS+1))           # assuming log-normal errors
  }
bs~dlnorm(0,0.001)     # Prior for the survey bias
CVS~dbeta(2,8)       # prior for the CV of survey data
surv50~dunif(0,30)
sdsurv~dunif(0,30)

}

