  note={MS submitted to the Journal of Eye Movement Research},
  year={2015},
  abstract = {This is the first attempt at characterizing reading difficulty in Hindi in naturally occurring sentences. We created the Potsdam-Allahabad Hindi Eyetracking Corpus by recording eye-movement data from 30 participants at the University of Allahabad, India. The target stimuli were 153 sentences selected from the beta version of the Hindi-Urdu treebank. We find that word or low-level predictors (word length, unigram and bigram frequency) affect first-pass reading times, regression path duration, total reading time, and outgoing saccade length, An increase in word length results in longer fixations, and an increase in word unigram and bigram frequency results in shorter fixations. Longer word length led to longer outgoing saccades, and higher frequency (unigram and bigram) also led to longer outgoing saccades. We also find that two predictors of sentence comprehension difficulty, integration and storage cost (computed based on Dependency Locality Theory, Gibson, 2000) affect regression path duration, total reading time, and outgoing saccade length. Integration cost is approximated by calculating the distance (in words) between a dependent and head; and storage cost measures difficulty of maintaining predictions by counting the number of predicted heads at each point in the sentence. Thus, word-level predictors have an effect in both early and late measures of reading time, while predictors of sentence comprehension difficulty affect later measures, suggesting that classical psycholinguistic measures of working memory difficulty have strong effects on fixation measures in reading.},
  pdf = {http://web.iitd.ernet.in/~samar/data/HusainEtAlETHindi.pdf}
