Now, I followed your suggestion and created GLM-style model, as below:

data {
  int<lower=1> n;
  vector<lower=0>[n] y;

  real<lower=0> sigma_prior_mu;
  real<lower=0> sigma_prior_sigma;

  real<lower=0> sigma_level_prior_mu;
  real<lower=0> sigma_level_prior_sigma;
  real<lower=0> sigma_trend_prior_mu;
  real<lower=0> sigma_trend_prior_sigma;
}
transformed data {
  real MIN_SIGMA;
  real maxY;
  MIN_SIGMA<-0.05;
  maxY <- max(y);
}
parameters {
  real<lower=1,upper=15> nu;
  real<lower=MIN_SIGMA> sigma;
  real<lower=0> sigma_level;
  real<lower=0> sigma_trend;
  real <lower=0,upper=1> powx;
  vector[n] levelError;
  vector[n] trendError;
}
transformed parameters {
  vector<lower=0>[n] lev;
  vector<lower=-log(maxY), upper=log(maxY)>[n] b;
  vector<lower=0, upper=log(maxY)*1.5>[n] l;
  lev[1] <- y[1];
  l[1]<-log(lev[1]);
  b[1] <- 0;

  for (t in 2:n) {

    b[t] <- b[t-1] + trendError[t];
    l[t] <- l[t-1]+ b[t-1]+ levelError[t];

    lev[t] <- exp(l[t]);
  }
}
model {
  real expectedLevel;
  //priors
  sigma ~ normal(sigma_prior_mu, sigma_prior_sigma) T[MIN_SIGMA,];
  sigma_level ~ normal(sigma_level_prior_mu, sigma_level_prior_sigma) T[0,];
  sigma_trend ~ normal(sigma_trend_prior_mu, sigma_trend_prior_sigma) T[0,];

  //model

  trendError ~ normal(0,sigma_trend);//vector
  levelError ~ normal(0,sigma_level);

  for (t in 2:n) {

    expectedLevel <- exp(l[t-1]+b[t-1]);
    y[t] ~ student_t(nu, expectedLevel , sigma*expectedLevel^powx);

  }
}
generated quantities {
  real innov;
  real positiveInnovations;
  real negativeInnovations;

  real expectedL;

  positiveInnovations <- 0;
  negativeInnovations <- 0;

  for (t in 2:n) {

    expectedL <- exp(l[t-1]+b[t-1]);
    innov <- y[t] - expectedL;

    if (innov>=0)
      positiveInnovations <- positiveInnovations+innov;
    else
      negativeInnovations <- negativeInnovations-innov;
  }
}

